from .csv_export import write_csv
from .finder import find_mkv_files


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="mkv-lister",
        description="Listet alle .mkv-Dateien in einem angegebenen Ordner auf.",
    )
    parser.add_argument(
        "directory",
        type=Path,
        help="Pfad zum zu durchsuchenden Ordner",
    )
    parser.add_argument(
        "-r",
        "--recursive",
        action="store_true",
        help="Auch Unterordner durchsuchen",
    )
    parser.add_argument(
        "--csv",
        type=Path,
        default=None,
        metavar="DATEI",
        help=(
            "Ergebnisse zusätzlich als CSV-Datei speichern "
            "(Spalten: Pfad;Dateiname;Jahr;Size, UTF-8)"
        ),
    )
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    try:
        files = find_mkv_files(args.directory, recursive=args.recursive)
    except (FileNotFoundError, NotADirectoryError) as exc:
        print(f"Fehler: {exc}", file=sys.stderr)
        return 1

    if not files:
        print("Keine .mkv-Dateien gefunden.")
    else:
        for file in files:
            print(file)

    if args.csv is not None:
        try:
            write_csv(files, args.csv)
        except OSError as exc:
            print(f"Fehler beim Schreiben der CSV-Datei: {exc}", file=sys.stderr)
            return 1
        print(f"CSV-Datei geschrieben: {args.csv}")

    return 0

def test_format_size_gigabytes() -> None:
    assert format_size(int(1.5 * 1024 ** 3)) == "1.50 GB"


def test_format_size_beyond_petabytes_falls_back_to_exabytes() -> None:
    assert format_size(2 * 1024 ** 6) == "2.00 EB"
